namespace ghidra.util.table.field;





using docking.widgets.table;
using ghidra.docking.settings;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.util.table.column;
using ghidra.util.table.column;

/**
 * This table field displays the reference type for the reference 
 * associated with a row in the table.
 */
public class ReferenceTypeTableColumn : ProgramLocationTableColumnExtensionPoint<Reference, RefType> {

	private ReferenceTypeTableCellRenderer reftypeRenderer = new ReferenceTypeTableCellRenderer();

	/* @Override */
	public string getColumnDisplayName(Settings settings) {
		return getColumnName();
	}

	/* @Override */
	public string getColumnName() {
		return "Ref Type";
	}

	/* @Override */
	public RefType getValue(Reference rowObject, Settings settings, Program program,
			ServiceProvider serviceProvider)
    {
		Listing listing = program.getListing();
		RefType referenceType = rowObject.getReferenceType();
		if (referenceType == RefType.INDIRECTION) {
			Instruction instruction = listing.getInstructionAt(rowObject.getFromAddress());
			if (instruction != null) {
				FlowType flowType = instruction.getFlowType();
				return flowType;
			}
		}
		return referenceType;
	}

	/* @Override */
	public ProgramLocation getProgramLocation(Reference rowObject, Settings settings,
			Program program, ServiceProvider serviceProvider) {
		return null;
	}

	/* @Override */
	public GColumnRenderer<RefType> getColumnRenderer() {
		return reftypeRenderer;
	}

	private class ReferenceTypeTableCellRenderer : AbstractGhidraColumnRenderer<RefType> {

		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {

			JLabel label = (JLabel) base.getTableCellRendererComponent(data);

			RefType value = (RefType) data.getValue();
			label.setText(value.getDisplayString());
			return label;
		}

		/* @Override */
		public string getFilterString(RefType t, Settings settings) {
			return t.getDisplayString();
		}
	}
}
